#include <iomanip>
#include <iostream>
#include "mesh/cubed_sphere/cross_face_boundary_probe.hpp"
#include "mesh/cubed_sphere/geometry_collar_probe.hpp"
#include "mesh/cubed_sphere/surface_mls_probe.hpp"
namespace c=cubed_sphere;
std::array<c::Jet,4> Exact(const Real*x){c::Jet X=c::Jet::Variable(x[0],0),Y=c::Jet::Variable(x[1],1),Z=c::Jet::Variable(x[2],2),R=c::Power(X*X+Y*Y+Z*Z,.5),nx=X/R,ny=Y/R,nz=Z/R,t=R-c::Jet(1);return {c::Jet(3.14159),c::Jet(1)+c::Jet(.2)*nx+c::Jet(.3)*nx*ny+c::Jet(.4)*ny*nz+c::Jet(.1)*nx*nx*nx,t*(c::Jet(.3)*nx+c::Jet(.5)*ny*nz+c::Jet(.2)*nx*nx)+t*t*(c::Jet(1)+c::Jet(.1)*nx*nz)+c::Jet(.1)*t*t*t*nz,X*Y+c::Jet(2)*Y*Z+c::Jet(3)*X*X*Z};}
struct Norm {Real first=0,second=0,mixed=0,value=0;Real field_first[4]{},field_second[4]{},field_mixed[4]{};size_t count=0;void Add(const c::CrossFaceBoundaryProbe::Jets&u,const std::array<c::Jet,4>&e,const Real*x){++count;for(int f=1;f<4;++f){value=std::max(value,std::abs(u.value[f]-e[f].f));for(int i=0;i<3;++i){first=std::max(first,std::abs(u.d[f][i]-e[f].d[i]));field_first[f]=std::max(field_first[f],std::abs(u.d[f][i]-e[f].d[i]));for(int j=0;j<3;++j){second=std::max(second,std::abs(u.dd[f][i][j]-e[f].h[i][j]));field_second[f]=std::max(field_second[f],std::abs(u.dd[f][i][j]-e[f].h[i][j]));}}for(int k=0;k<3;++k){Real m=0;for(int i=0;i<3;++i)for(int j=0;j<3;++j)m+=x[i]*(u.dd[f][i][j]-e[f].h[i][j])*((j==k?1.:0)-x[j]*x[k]);mixed=std::max(mixed,std::abs(m));field_mixed[f]=std::max(field_mixed[f],std::abs(m));}}}void Print()const{std::cout<<"{\"count\":"<<count<<",\"value_max\":"<<value<<",\"first_max\":"<<first<<",\"second_max\":"<<second<<",\"normal_tangent_hessian_max\":"<<mixed<<",\"fields\":[";for(int f=1;f<4;++f){if(f>1)std::cout<<',';std::cout<<"{\"first\":"<<field_first[f]<<",\"second\":"<<field_second[f]<<",\"mixed\":"<<field_mixed[f]<<'}';}std::cout<<"]}";}};
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int result=0;try{if(argc<5||argc>9)throw std::runtime_error("n shells subdivisions radial_nodes");const int n=std::stoi(argv[1]),layers=std::stoi(argv[2]),sub=std::stoi(argv[3]),radial=std::stoi(argv[4]);std::vector<Real> radii=layers==1?std::vector<Real>{1}:layers==2?std::vector<Real>{.65,1}:std::vector<Real>{.45,.55,.60,.65,.70,.75,1};c::CompositeMesh mesh(.25,radii,sub,n,2);if(mesh.blocks.size()*size_t(n)*n*n>50000)throw std::runtime_error("bounded50000");c::CompositeDifference grid(mesh,4);c::ScriSurface surface(grid,4,radial);std::vector<Real> volume(4*grid.count,0),boundary(surface.values.size());for(size_t p=0;p<grid.active.size();++p){auto u=Exact(grid.geometry[p].x);for(int f=0;f<4;++f)volume[f*grid.count+grid.active[p]]=u[f].f;}for(size_t p=0;p<surface.rows.size();++p){auto u=Exact(surface.rows[p].geometry.x);for(int f=0;f<4;++f)boundary[4*p+f]=u[f].f;}c::CrossFaceBoundaryProbe probe(surface,volume,boundary,4);Norm all,edge,corner,seam,oracle_all,oracle_seam;Real constant=0,pure_normal_error=0;std::cout<<std::setprecision(17);
 auto inspect=[&](int block,const Real*q,Norm&norm,bool row,size_t p){const auto geometry=mesh.Geometry(block,q);const auto u=probe.At(block,q);norm.Add(u,Exact(geometry.x),geometry.x);constant=std::max(constant,std::abs(u.value[0]-3.14159));for(int i=0;i<3;++i){constant=std::max(constant,std::abs(u.d[0][i]));for(int j=0;j<3;++j)constant=std::max(constant,std::abs(u.dd[0][i][j]));}if(row){const auto old=surface.Sample(p,volume,boundary,4);for(int f=0;f<4;++f){Real d=0,dd=0;for(int i=0;i<3;++i){d+=geometry.x[i]*(u.d[f][i]-old.d[f][i]);for(int j=0;j<3;++j)dd+=geometry.x[i]*geometry.x[j]*(u.dd[f][i][j]-old.dd[f][i][j]);}pure_normal_error=std::max({pure_normal_error,std::abs(d),std::abs(dd)});}}};
 for(size_t p=0;p<surface.rows.size();++p){auto &row=surface.rows[p];const Real q[3]={1,(row.j+.5)/n,(row.k+.5)/n};inspect(row.block,q,all,true,p);const bool a=row.j<2||row.j>=n-2,b=row.k<2||row.k>=n-2;if(a||b)inspect(row.block,q,a&&b?corner:edge,false,p);}
 for(size_t b=0;b<mesh.blocks.size();++b)if(surface.base[b]>=0)for(int j=0;j<=n;++j){Real q[3]={1,0,Real(j)/n};inspect(b,q,seam,false,0);q[1]=1;inspect(b,q,seam,false,0);q[1]=Real(j)/n;q[2]=0;inspect(b,q,seam,false,0);q[2]=1;inspect(b,q,seam,false,0);}
 Norm owner_all=all,owner_seam=seam;all=Norm{};edge=Norm{};corner=Norm{};seam=Norm{};c::GeometryCollarProbe volume_mls(surface,volume,boundary,4);c::SurfaceMLSProbe surface_mls(mesh,4);surface_mls.values=boundary;probe.off_node_query=[&](int block,const Real*q,bool endpoint){if(false){Real x[3];mesh.Forward(block,q,x);return surface_mls.Sample(x);}return volume_mls.Sample(block,q);};
 for(size_t p=0;p<surface.rows.size();++p){auto &row=surface.rows[p];const Real q[3]={1,(row.j+.5)/n,(row.k+.5)/n};inspect(row.block,q,all,true,p);const bool a=row.j<2||row.j>=n-2,b=row.k<2||row.k>=n-2;if(a||b)inspect(row.block,q,a&&b?corner:edge,false,p);}
 for(size_t b=0;b<mesh.blocks.size();++b)if(surface.base[b]>=0)for(int j=0;j<=n;++j){Real q[3]={1,0,Real(j)/n};inspect(b,q,seam,false,0);q[1]=1;inspect(b,q,seam,false,0);q[1]=Real(j)/n;q[2]=0;inspect(b,q,seam,false,0);q[2]=1;inspect(b,q,seam,false,0);}
 probe.exact_mms_query=[](const Real*x){auto u=Exact(x);std::vector<Real> out(4);for(int f=0;f<4;++f)out[f]=u[f].f;return out;};for(const auto &row:surface.rows){const Real q[3]={1,(row.j+.5)/n,(row.k+.5)/n};inspect(row.block,q,oracle_all,false,0);}for(size_t b=0;b<mesh.blocks.size();++b)if(surface.base[b]>=0)for(int j=0;j<=n;++j){Real q[3]={1,0,Real(j)/n};inspect(b,q,oracle_seam,false,0);q[1]=1;inspect(b,q,oracle_seam,false,0);q[1]=Real(j)/n;q[2]=0;inspect(b,q,oracle_seam,false,0);q[2]=1;inspect(b,q,oracle_seam,false,0);}
 std::cout<<"{\"method\":\""<<volume_mls.Method()<<"\",\"n\":"<<n<<",\"layers\":"<<layers<<",\"subdivisions\":"<<sub<<",\"radial_nodes\":"<<radial<<",\"cells\":"<<grid.active.size()<<",\"physical_owner_J_scaling\":"<<true<<",\"outer_active_pool_only\":"<<true<<",\"unified_volume_boundary_MLS\":"<<1<<",\"volume_MLS_donors\":"<<surface.radial_nodes*volume_mls.angular_donors<<",\"fixed_radial_angular_plan_count\":"<<volume_mls.PlanCount()<<",\"volume_MLS_rows\":"<<volume_mls.rows_built<<",\"volume_MLS_max_l1\":"<<volume_mls.maximum_l1<<",\"volume_MLS_QR_R_condition_infinity\":"<<volume_mls.maximum_condition<<",\"volume_MLS_max_poly_reproduction\":"<<volume_mls.maximum_reproduction<<",\"surface_MLS_max_l1\":"<<surface_mls.maximum_l1<<",\"surface_MLS_QR_R_condition_infinity\":"<<surface_mls.maximum_condition<<",\"constant_max\":"<<constant<<",\"original_pure_normal_jet_difference_max\":"<<pure_normal_error<<",\"all_surface\":";all.Print();std::cout<<",\"edge_band\":";edge.Print();std::cout<<",\"corner_band\":";corner.Print();std::cout<<",\"exact_patch_seams_and_corners\":";seam.Print();std::cout<<",\"owner_all_surface\":";owner_all.Print();std::cout<<",\"owner_exact_seams\":";owner_seam.Print();std::cout<<",\"analytic_pullback_all_surface\":";oracle_all.Print();std::cout<<",\"analytic_pullback_exact_seams\":";oracle_seam.Print();std::cout<<"}\n";if(constant>1e-13||pure_normal_error>1e-9||!std::isfinite(all.first+all.second+seam.first+seam.second))throw std::runtime_error("boundary probe constant/normal/finite consistency failed");
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';result=2;}Kokkos::finalize();return result;}
